contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive with depositor address being this contract (calls originate from this),
    // depositAmount is the value to deposit; later we assert recorded balance >= depositAmount.
    function check_deposit_no_wrap(uint256 depositAmount) public payable {
        // ensure we have enough ETH to send
        require(address(this).balance >= depositAmount);

        // perform deposit into C from this contract
        c.deposit{value: depositAmount}();

        // Observe: C has a private mapping balances; but we can observe address(c).balance.
        // However the distinguishing behavior is that in the original contract the stored
        // per-account balance cannot wrap, so the stored balance for msg.sender will be >= depositAmount.
        // There is no public getter for balances, so we infer per-account stored balance by
        // performing a withdraw of (address(c).balance) back to this contract only if allowed.
        // To directly observe whether the stored balance for this contract is at least depositAmount,
        // attempt to withdraw depositAmount (should succeed under original contract) and then
        // re-deposit to restore state if needed.

        // Attempting withdraw of depositAmount: under P this will succeed (require passes),
        // under M (if wrap occurred) the stored balance might be < depositAmount and withdraw will revert.
        // We capture the revert boolean.
        bool didRevert;
        // Use low-level call to capture revert without bubbling
        (didRevert, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", depositAmount));

        // Final assertion: withdrawal must not revert — meaning recorded balance for this caller is >= depositAmount.
        assert(didRevert == false);
    }

    // allow this contract to receive ETH
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No special precondition needed
        bool reverted;
        // Call deposit sending the Ether we received to this test
        // Ensure the test contract has the Ether to forward
        require(address(this).balance >= msg.value);
        try c.deposit{value: msg.value}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // On the original contract, deposit never reverts for any msg.value; the mutant can cause different behavior
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // Rule: when caller can send the requested amount, deposit should not revert
        assert(!(amount > 0 && reverted == true));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // take an arbitrary depositor amount and perform deposit from this test contract
    function run(uint256 initialDeposit, uint256 triggerDeposit) public payable {
        // require this test contract holds enough Ether to perform both deposits
        require(address(this).balance >= initialDeposit + triggerDeposit);
        // first deposit some Ether to set up a large existing balance
        bool reverted;
        try c.deposit{value: initialDeposit}() { reverted = false; } catch { reverted = true; }
        // boundary call: try to deposit triggerDeposit which may overflow balances in mutant
        bool reverted2;
        try c.deposit{value: triggerDeposit}() { reverted2 = false; } catch { reverted2 = true; }
        // General rule: In the original contract the first deposit cannot revert (normal use),
        // and the second deposit will revert only if triggerDeposit is zero and no other reason.
        // We assert that if both deposits had positive value available from this contract,
        // then the second call must not revert unless triggerDeposit == 0. This is violated by M when wraparound is allowed.
        assert(!(initialDeposit + triggerDeposit > 0 && !reverted && triggerDeposit > 0) || reverted2 == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // we take priorBalanceHigh as a flag parameter to indicate we want the caller's prior recorded balance
    // to be large enough that adding amount would overflow in unchecked arithmetic. We cannot read balances,
    // so we instead require that address(c).balance is large enough for the test contract to fund the deposit.
    function run(uint256 amount) public payable {
        // ensure this test contract has enough Ether to send
        require(address(this).balance >= amount);
        // call deposit on c sending `amount` wei
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The original contract enforces an overflow check, so deposit should revert if and only if
        // amount == 0 would not revert but overflow would be prevented; more directly: when amount > 0
        // and the caller can send it, deposit must NOT revert in the original because of the assert that
        // balances[msg.sender] + amount > balances[msg.sender]. However, the mutant removes that check
        // and can silently wrap instead of reverting. We assert that if we attempted to send a positive
        // amount then deposit did NOT revert. This holds for the original but is violated by the mutant
        // when wrapping occurs.
        assert(!(amount > 0) || reverted == false);
    }
    receive() external payable { }
}

