pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz two deposit amounts and an actor address
    function testFuzz_property(address depositor, uint256 a, uint256 b) public {
        // keep depositor as a non-zero address to be a proper actor
        vm.assume(depositor != address(0));

        // fund depositor so they can send the amounts
        vm.deal(depositor, a + b);

        // first deposit
        vm.prank(depositor);
        c.deposit{value: a}();
        // read recorded balance after first deposit via the autogenerated getter
        uint256 after1 = address(c).balance; // overall contract balance
        // but we must observe depositor's recorded balance; balances is not public in C, so we
        // instead use behavior visible via contract balance combined with controlled single depositor flows.
        // To ensure we can reason about depositor's recorded balance without a getter, execute a second
        // deposit and confirm that the per-depositor recorded balance does not decrease by observing that
        // calling withdraw of an amount equal to a + b (bounded by recorded balance) does not revert when
        // the recorded balance is at least a+b. We implement a strategy: after two deposits, attempting to
        // withdraw a small known amount that should be <= recorded balance will succeed on the correct
        // contract but may fail on the mutant where wraparound made the recorded balance tiny.

        // second deposit
        vm.prank(depositor);
        c.deposit{value: b}();

        // Now probe whether the depositor's recorded balance is at least min(a, 1) (choose 1 if both zero)
        // We will attempt to withdraw 1 wei and see it succeeds. If total recorded balance wrapped to 0,
        // withdraw(1) will revert. We need to ensure depositor had at least 1 deposited in total originally,
        // so require a + b >= 1 to make this admissible; otherwise the property is vacuously true.
        vm.assume(a + b >= 1);

        // Try withdrawing 1 wei; catch revert to observe success/failure
        bool ok;
        vm.prank(depositor);
        try c.withdraw(1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: after two deposits by the same depositor totaling >=1, withdrawing 1 wei must succeed
        // on the correct contract (no overflow wrap), but the mutant that allows wraparound can make the
        // recorded balance < 1 and cause withdraw(1) to revert for some inputs. Assert this property.
        assertTrue(ok);
    }
}

