pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz three parameters:
    // - addrA: an initial depositor who makes a deposit
    // - addrB: a second sender who will deposit via a helper that forwards the value; kept distinct from addrA so two different senders are used
    // - v: the value addrB sends in its deposit (large values can trigger overflow when added to addrA's existing balance)
    function testFuzz_property(address addrA, address addrB, uint256 v) public {
        // Keep addresses distinct and non-zero to avoid trivialities
        vm.assume(addrA != address(0));
        vm.assume(addrB != address(0));
        vm.assume(addrA != addrB);

        // We want addrA to have a nonzero initial balance so second deposit can cause overflow.
        // Choose an initial deposit amount w that is moderately large but allow fuzz to choose; use bound to keep it wide.
        uint256 w = bound(uint256(uint160(addrA)) ^ v, 1, type(uint256).max / 2);

        // Fund addrA and addrB
        vm.deal(addrA, w);
        vm.deal(addrB, v);

        // addrA makes initial deposit w
        vm.prank(addrA);
        c.deposit{value: w}();

        // Record balance after first deposit (via public getter auto-generated for balances mapping)
        uint256 before = c.balances(addrA);

        // Deploy a forwarder that will, when told, forward its entire msg.value to c.deposit on behalf of addrB.
        Forwarder f = new Forwarder(c);

        // addrB sends v to Forwarder which forwards to c.deposit (so c.deposit sees msg.sender == Forwarder)
        // We ensure Forwarder is used so the deposit originates from a contract (not EOA) to explore behavior under contract caller.
        vm.prank(addrB);
        // send value v to forwarder which will call c.deposit{value: msg.value}()
        (bool sent,) = address(f).call{value: v}(abi.encodeWithSelector(Forwarder.forward.selector));
        // The call should succeed (we don't restrict); whether c.deposit wraps is what we check
        // Record balance of addrA after the forwarded deposit
        uint256 after = c.balances(addrA);

        // General property: In the reference contract, for any admissible inputs the recorded balance for addrA after others' deposits cannot be less than before (i.e., deposit never reduces previously recorded balances of other accounts); the mutant that removes the overflow assert can cause wraparound making `after < before` for some inputs. Assert that after >= before.
        assertTrue(after >= before);
    }
}

// Minimal forwarder that forwards its received value into c.deposit when asked
contract Forwarder {
    C public target;
    constructor(C _t) payable { target = _t; }
    function forward() external payable {
        // forward entire msg.value into target.deposit
        target.deposit{value: msg.value}();
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    // depositor: address that will call deposit (must be this contract)
    // depositAmount: amount of wei to send with deposit
    function runTest(uint256 depositAmount) public {
        // must have funds to send
        require(address(this).balance >= depositAmount);
        // record contract-visible balance mapping before
        uint256 before = c.balances(address(this));

        // perform deposit on c sending depositAmount wei
        c.deposit{value: depositAmount}();

        // record after
        uint256 after = c.balances(address(this));

        // General rule: after >= before + depositAmount for any depositAmount>0
        // Use require to ensure meaningful depositAmount
        require(depositAmount > 0);
        assert(after >= before + depositAmount);
    }

    // allow this contract to receive ether so it can call deposit
    receive() external payable {}
}

