pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: actor (caller) and amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep domain sensible: actor cannot be zero-address and amount should be small enough to fund
        vm.assume(actor != address(0));
        // bound amount to a reasonable range to avoid overflows in the test harness and to ensure vm.deal feasible
        uint256 amt = bound(amount, 1, 1 ether);

        // fund the actor so they can send amt
        vm.deal(actor, amt);

        // record pre-call balance via public getter: balances is not public in source, so we must infer by making a deposit and comparing
        // The contract C does not expose balances mapping; to observe the effect we rely on the reference behavior that
        // after deposit the caller's balance as tracked by the contract increases by amt. We test this by performing two deposits
        // and checking that the second deposit increases the contract's recorded balance by exactly amt (by comparing change in address(c).balance
        // is not sufficient because deposit updates internal mapping, but refund/migrate/withdraw affect external balance; however withdraw/refund
        // require reading balances[msg.sender] which is internal, so instead we use refund to read out the stored balance: calling refund transfers their stored balance to caller.

        // Make first deposit
        vm.prank(actor);
        c.deposit{value: amt}();

        // Now perform a second deposit of amt2 (use 1 to observe increase) and then call refund to observe stored balance
        uint256 amt2 = 1 wei;
        vm.deal(actor, amt2);
        vm.prank(actor);
        c.deposit{value: amt2}();

        // After two deposits, the stored balance for actor should equal amt + amt2 (in the correct contract).
        // We observe the stored balance by calling refund(), which transfers the stored balance to the caller and resets it to 0.
        // Capture actor's ether balance before refund to compute how much was refunded.
        uint256 before = actor.balance;
        vm.prank(actor);
        c.refund();
        uint256 after = actor.balance;

        uint256 refunded = after - before;

        // The universal property: refunded amount equals amt + amt2 for the correct contract, for all admissible inputs.
        // The mutant that sets balances[msg.sender] = 0 in deposit will cause refunded to be less than expected for many inputs.
        assertTrue(refunded == amt + amt2);
    }
}

