pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor and the deposit/withdraw amount
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound depositAmount to a reasonable non-zero range so we can send value
        depositAmount = bound(depositAmount, 1, 1 ether);
        // place withdrawAmount in wide range but will be constrained by require in contract
        withdrawAmount = bound(withdrawAmount, 0, 1 ether);

        // fund the actor externally so they can deposit
        vm.deal(actor, depositAmount);
        // actor deposits depositAmount
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // ensure actor had at least withdrawAmount in recorded balances; if not, skip (uninteresting)
        // we allow withdrawAmount == 0 as admissible
        vm.assume(withdrawAmount <= depositAmount);

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // perform withdraw as the actor; capture whether it succeeded
        bool ok;
        vm.prank(actor);
        try c.withdraw(withdrawAmount) { ok = true; } catch { ok = false; }

        // After a successful withdraw, the reference contract always reduces its balance by exactly withdrawAmount.
        // The mutant that sends (withdrawAmount - 1) will cause address(c).balance to decrease by only (withdrawAmount - 1)
        // while still deducting withdrawAmount from the stored balance, creating a discrepancy. We assert the universal
        // property that when withdraw succeeds, address(c).balance == before - withdrawAmount.
        // This holds for the reference implementation for all inputs, but the mutant fails for some inputs.
        if (ok) {
            assertTrue(address(c).balance == before - withdrawAmount);
        } else {
            // If the call reverted (shouldn't for admissible inputs here), still assert nothing about balance change.
            // To satisfy the single assert rule, assert the contract balance is unchanged when withdraw reverted.
            assertTrue(address(c).balance == before);
        }
    }
}
